import {changedDraftFields} from "@/lib/draftConflict";
import {useLiveQuery} from "dexie-react-hooks";
import {ArrowDown, ArrowUp, Copy, CopyPlus, Plus, Trash2} from "lucide-react";
import {useEffect, useRef, useState} from "react";
import {db} from "@/db/database";
import {
    addStoryBeat,
    deleteShots,
    deleteStoryBeat,
    duplicateBeat,
    patchStoryBeat,
    reorderBeats,
    restoreStoryBeat,
    updateEpisodeDraft,
} from "@/db/repo";
import {type Episode, normalizeEpisodeStory, type StoryBeat} from "@/domain/types";
import {Button} from "@/components/ui/button";
import {Checkbox} from "@/components/ui/checkbox";
import {DraftStatus} from "@/components/ui/draft-status";
import {Input} from "@/components/ui/input";
import {Label} from "@/components/ui/label";
import {Select, SelectContent, SelectItem, SelectTrigger, SelectValue,} from "@/components/ui/select";
import {Textarea} from "@/components/ui/textarea";
import {useDebouncedDraft} from "@/lib/debouncedDraft";
import {useUndo} from "@/lib/undo";
import {cn} from "@/lib/utils";

function isScriptFile(file: File): boolean {
    const name = file.name.toLowerCase();
    if (name.endsWith(".txt") || name.endsWith(".md") || name.endsWith(".markdown")) return true;
    return file.type === "text/plain" || file.type === "text/markdown" || file.type === "text/x-markdown";
}

export function StoryPage({projectId, episodeId}: { projectId: string; episodeId: string }) {
    const project = useLiveQuery(async () => (await db.projects.get(projectId)) ?? null, [projectId]);
    const episode = useLiveQuery(
        async () => (await db.episodes.get(episodeId)) ?? null,
        [episodeId],
    );
    const characters =
        useLiveQuery(
            () => db.characters.where("projectId").equals(projectId).toArray(),
            [projectId],
        ) ?? [];
    const scenes =
        useLiveQuery(() => db.scenes.where("projectId").equals(projectId).toArray(), [projectId]) ?? [];
    if (episode === undefined || project === undefined) {
        return <div className="text-muted-foreground p-8 text-sm">加载故事…</div>;
    }
    if (project === null || episode === null || episode.projectId !== projectId) {
        return <div className="text-muted-foreground p-8 text-sm">找不到这一集</div>;
    }

    return (
        <StoryEditor
            key={episode.id}
            episode={episode}
            film={project.mode === "film"}
            characters={characters}
            scenes={scenes}
        />
    );
}

type ScriptImport = {request: number; name: string; text: string};
type ScriptImportSession = {scope: string; request: number; revision: number; candidate?: ScriptImport};

function StoryEditor({
                         episode,
                         film,
                         characters,
                         scenes,
                     }: {
    episode: Episode;
    film: boolean;
    characters: { id: string; name: string }[];
    scenes: { id: string; name: string }[];
}) {
    const initialStory = normalizeEpisodeStory(episode.story);
    const {draft, setDraft, status, error, retry, useLatest, flush} = useDebouncedDraft({
        draftKey: `episode:${episode.id}:story`,
        scope: episode.projectId,
        initialValue: {
            title: episode.title,
            logline: initialStory.logline,
            script: initialStory.script,
        },
        persist: (value, baseline) => updateEpisodeDraft(episode.id, changedDraftFields(value, baseline), baseline),
    });
    const [dragging, setDragging] = useState(false);
    const scriptRef = useRef<HTMLTextAreaElement>(null);
    const {registerUndo} = useUndo();
    const beats = normalizeEpisodeStory(episode.story).beats;

    function updateBeat(id: string, change: Partial<StoryBeat>) {
        void patchStoryBeat(episode.id, id, change);
    }

    const mounted = useRef(true);
    const importSession = useRef<ScriptImportSession>({scope: `${episode.projectId}:${episode.id}`, request: 0, revision: 0});
    if (importSession.current.scope !== `${episode.projectId}:${episode.id}`) {
        importSession.current = {scope: `${episode.projectId}:${episode.id}`, request: 0, revision: 0};
    }
    const session = importSession.current;
    const [importCandidate, setImportCandidate] = useState<ScriptImport>();
    const [importError, setImportError] = useState<string>();
    const candidate = importCandidate === session.candidate ? importCandidate : undefined;

    useEffect(() => {
        mounted.current = true;
        return () => {
            mounted.current = false;
            session.request += 1;
            session.candidate = undefined;
        };
    }, [session]);

    function currentSession() {
        return mounted.current && importSession.current === session;
    }

    function useLatestStory() {
        if (!currentSession()) return;
        session.revision += 1;
        session.request += 1;
        session.candidate = undefined;
        setImportCandidate(undefined);
        setImportError(undefined);
        useLatest();
    }

    function changeScript(value: string) {
        if (!currentSession()) return;
        // Count every edit, including edit-then-revert, rather than comparing
        // text at completion. A conflict candidate remains an explicit choice.
        session.revision += 1;
        setDraft((current) => ({...current, script: value}));
    }

    function decideImport(adopt: boolean) {
        if (!currentSession() || !candidate || session.candidate !== candidate) return;
        session.request += 1;
        session.candidate = undefined;
        setImportCandidate(undefined);
        if (adopt) changeScript(candidate.text);
    }

    async function applyScriptFile(file: File) {
        if (!currentSession() || !isScriptFile(file)) return;
        const request = ++session.request;
        const revision = session.revision;
        session.candidate = undefined;
        setImportCandidate(undefined);
        setImportError(undefined);
        try {
            const text = await file.text();
            if (!currentSession() || request !== session.request) return;
            if (revision !== session.revision) {
                const next = {request, name: file.name, text};
                session.candidate = next;
                setImportCandidate(next);
            } else {
                changeScript(text);
            }
        } catch {
            if (currentSession() && request === session.request) setImportError("读取剧本失败，请重新拖入文件重试。");
        }
    }

    async function addBeatFromSelection() {
        const textarea = scriptRef.current;
        if (!textarea || textarea.selectionStart === textarea.selectionEnd) return;
        const start = textarea.selectionStart;
        const end = textarea.selectionEnd;
        const excerpt = draft.script.slice(start, end);
        if (!excerpt) return;
        await flush();
        await addStoryBeat(episode.id, {scriptRange: {start, end, excerpt}});
    }

    async function moveBeat(index: number, offset: -1 | 1) {
        const target = index + offset;
        if (target < 0 || target >= beats.length) return;
        const previous = beats.map((beat) => beat.id);
        const next = [...previous];
        [next[index], next[target]] = [next[target]!, next[index]!];
        await reorderBeats(episode.id, next);
        registerUndo({
            label: "已调整场次顺序",
            restore: () => reorderBeats(episode.id, previous),
        });
    }

    async function removeBeat(beat: StoryBeat, index: number) {
        const shotIds = (await db.shots.where("episodeId").equals(episode.id).toArray())
            .filter((shot) => shot.beatId === beat.id)
            .map((shot) => shot.id);
        await deleteStoryBeat(episode.id, beat.id);
        registerUndo({
            label: "已删除场次",
            restore: () => restoreStoryBeat(episode.id, beat, index, shotIds),
        });
    }

    async function copyBeat(beatId: string, copyShots: boolean) {
        const copy = await duplicateBeat(episode.id, beatId, {includeShots: copyShots});
        registerUndo({
            label: copyShots ? "已复制场次及镜头" : "已复制场次",
            restore: async () => {
                await deleteShots(copy.shots.map((shot) => shot.id));
                await deleteStoryBeat(episode.id, copy.beat.id);
            },
        });
    }

    return (
        <div className="app-scroll h-full overflow-auto">
            <div
                className="mx-auto grid max-w-6xl gap-8 px-4 py-6 sm:px-8 sm:py-8 lg:grid-cols-[minmax(0,1.4fr)_minmax(20rem,0.8fr)]">
                <section className="min-w-0">
                    <div className="flex items-end justify-between gap-4">
                        <div>
                            <h1 className="text-[17px] font-semibold">{film ? "故事" : "本集故事"}</h1>
                            <p className="text-muted-foreground mt-1 text-xs">
                                {film ? "先写这部作品要讲什么。" : "先写这一集要讲什么。"}场次可以后补，分镜会从这里长出来。
                            </p>
                        </div>
                        <DraftStatus status={status} error={error} onRetry={() => void retry()}
                                     onUseLatest={useLatestStory}/>
                    </div>
                    <Label className="mt-6">{film ? "故事标题（可选）" : "集标题（可选）"}</Label>
                    <Input
                        className="mt-2"
                        value={draft.title}
                        placeholder={film ? "可填写这一稿的标题" : "不填就显示第几集"}
                        onChange={(event) => {
                            const value = event.target.value;
                            setDraft((current) => ({...current, title: value}));
                        }}
                    />
                    <Label className="mt-6">{film ? "一句话故事" : "本集一句话"}</Label>
                    <Input
                        className="mt-2"
                        value={draft.logline}
                        placeholder={film ? "这个故事，用一句话说完" : "这一集，用一句话说完"}
                        onChange={(event) => {
                            const value = event.target.value;
                            setDraft((current) => ({...current, logline: value}));
                        }}
                    />
                    <Label className="mt-6">剧本</Label>
                    <p className="text-muted-foreground mt-1 text-[11px]">可拖入 .txt / .md，写入正文，不会自动拆场。</p>
                    <div
                        className={cn("mt-2 rounded-xl", dragging && "ring-brand ring-2")}
                        onDragEnter={(event) => {
                            event.preventDefault();
                            setDragging(true);
                        }}
                        onDragOver={(event) => {
                            event.preventDefault();
                            setDragging(true);
                        }}
                        onDragLeave={() => setDragging(false)}
                        onDrop={(event) => {
                            event.preventDefault();
                            if (!currentSession()) return;
                            setDragging(false);
                            const file = event.dataTransfer.files[0];
                            if (file) void applyScriptFile(file);
                        }}
                    >
                        <Textarea
                            ref={scriptRef}
                            className="min-h-[28rem] resize-y bg-card/60 text-[14px] leading-7"
                            value={draft.script}
                            placeholder="直接贴剧本，或把 txt / md 拖进来。"
                            onChange={(event) => changeScript(event.target.value)}
                        />
                    </div>
                    {importError ? <p role="alert" className="text-destructive mt-2 text-xs">{importError}</p> : null}
                    {candidate ? (
                        <div className="bg-muted/40 mt-3 rounded-lg border p-3">
                            <p className="text-sm">读取 {candidate.name} 期间正文已修改，当前正文已保留。</p>
                            <pre className="mt-2 max-h-40 overflow-auto whitespace-pre-wrap text-xs">{candidate.text}</pre>
                            <div className="mt-3 flex gap-2">
                                <Button size="sm" onClick={() => decideImport(true)}>采用导入正文</Button>
                                <Button size="sm" variant="outline" onClick={() => decideImport(false)}>放弃导入</Button>
                            </div>
                        </div>
                    ) : null}
                </section>
                <aside className="min-w-0">
                    <div className="flex items-center justify-between">
                        <h2 className="text-sm font-medium">场次</h2>
                        <div className="flex gap-2">
                            <Button size="sm" variant="outline" onClick={() => void addBeatFromSelection()}>
                                从选中内容建场
                            </Button>
                            <Button size="sm" variant="outline" onClick={() => void addStoryBeat(episode.id)}>
                                <Plus/>
                                加一场
                            </Button>
                        </div>
                    </div>
                    <p className="text-muted-foreground mt-1 text-[11px] leading-5">
                        加一场，分镜里就会出现对应的空场。出场角色和地点从本戏世界选。
                    </p>
                    <ul className="mt-4 space-y-3">
                        {beats.length === 0 ? (
                            <li className="text-muted-foreground rounded-2xl border border-dashed px-4 py-8 text-center text-xs">
                                还没有场次
                            </li>
                        ) : (
                            beats.map((beat, index) => (
                                <li key={beat.id} className="bg-card rounded-2xl border p-3">
                                    <div className="flex items-center gap-2">
                                        <span className="text-muted-foreground w-6 text-xs">{index + 1}</span>
                                        <Input
                                            value={beat.title}
                                            onChange={(event) => updateBeat(beat.id, {title: event.target.value})}
                                            className="h-8"
                                        />
                                        <Button
                                            size="icon-sm"
                                            variant="ghost"
                                            aria-label="上移场次"
                                            disabled={index === 0}
                                            onClick={() => void moveBeat(index, -1)}
                                        >
                                            <ArrowUp/>
                                        </Button>
                                        <Button
                                            size="icon-sm"
                                            variant="ghost"
                                            aria-label="下移场次"
                                            disabled={index === beats.length - 1}
                                            onClick={() => void moveBeat(index, 1)}
                                        >
                                            <ArrowDown/>
                                        </Button>
                                        <Button
                                            size="icon-sm"
                                            variant="ghost"
                                            aria-label="复制场次"
                                            onClick={() => void copyBeat(beat.id, false)}
                                        >
                                            <Copy/>
                                        </Button>
                                        <Button
                                            size="icon-sm"
                                            variant="ghost"
                                            aria-label="复制场次及其镜头"
                                            onClick={() => void copyBeat(beat.id, true)}
                                        >
                                            <CopyPlus/>
                                        </Button>
                                        <Button
                                            size="icon-sm"
                                            variant="ghost"
                                            aria-label="删除场次"
                                            onClick={() => void removeBeat(beat, index)}
                                        >
                                            <Trash2/>
                                        </Button>
                                    </div>
                                    <Textarea
                                        className="mt-2 min-h-20 resize-none"
                                        value={beat.content}
                                        placeholder="这场发生什么"
                                        onChange={(event) => updateBeat(beat.id, {content: event.target.value})}
                                    />
                                    <Label className="mt-3 text-[11px]">出场角色</Label>
                                    <div
                                        className="mt-1 max-h-28 space-y-1 overflow-auto rounded-lg border px-2 py-1.5">
                                        {characters.length === 0 ? (
                                            <p className="text-muted-foreground text-[11px]">世界里还没有角色</p>
                                        ) : (
                                            characters.map((character) => (
                                                <label key={character.id} className="flex items-center gap-2 text-xs">
                                                    <Checkbox
                                                        checked={beat.characterIds.includes(character.id)}
                                                        onCheckedChange={(checked) => {
                                                            const ids = checked
                                                                ? [...beat.characterIds, character.id]
                                                                : beat.characterIds.filter((item) => item !== character.id);
                                                            updateBeat(beat.id, {characterIds: ids});
                                                        }}
                                                    />
                                                    {character.name}
                                                </label>
                                            ))
                                        )}
                                    </div>
                                    <div className="mt-3 grid grid-cols-2 gap-2">
                                        <div>
                                            <Label className="text-[11px]">地点</Label>
                                            <Select
                                                value={beat.sceneId ?? "none"}
                                                onValueChange={(value) =>
                                                    updateBeat(beat.id, {sceneId: value === "none" ? undefined : value})
                                                }
                                            >
                                                <SelectTrigger className="mt-1 h-8 w-full">
                                                    <SelectValue placeholder="未选择"/>
                                                </SelectTrigger>
                                                <SelectContent>
                                                    <SelectItem value="none">未选择</SelectItem>
                                                    {scenes.map((scene) => (
                                                        <SelectItem key={scene.id} value={scene.id}>
                                                            {scene.name}
                                                        </SelectItem>
                                                    ))}
                                                </SelectContent>
                                            </Select>
                                        </div>
                                        <div>
                                            <Label className="text-[11px]">时段</Label>
                                            <Input
                                                className="mt-1 h-8"
                                                value={beat.timeOfDay}
                                                placeholder="日 / 夜"
                                                onChange={(event) => updateBeat(beat.id, {timeOfDay: event.target.value})}
                                            />
                                        </div>
                                    </div>
                                </li>
                            ))
                        )}
                    </ul>
                </aside>
            </div>
        </div>
    );
}

import {SearchConnection} from "./SearchConnection";
import {useLiveQuery} from "dexie-react-hooks";
import {Check, Plug} from "lucide-react";
import {useEffect, useMemo, useRef, useState} from "react";
import {toast} from "sonner";
import {Badge} from "@/components/ui/badge";
import {Button} from "@/components/ui/button";
import {Card, CardAction, CardDescription, CardFooter, CardHeader, CardTitle,} from "@/components/ui/card";
import {
    Dialog,
    DialogContent,
    DialogDescription,
    DialogFooter,
    DialogHeader,
    DialogTitle,
} from "@/components/ui/dialog";
import {Field} from "@/components/ui/field";
import {Input} from "@/components/ui/input";
import {db} from "@/db/database";
import {deleteConnector, upsertConnector} from "@/db/repo";
import type {ConnectorConfig, ConnectorDefinitionId} from "@/domain/types";
import {CONNECTOR_CATALOG, type ConnectorDefinition} from "@/lib/ai/catalog";
import {maskApiKey} from "@/lib/ai/openaiCompatible";
import {listConnectorModels, testConnectorConnection} from "@/lib/ai/connectors";
import {cn} from "@/lib/utils";
import {redactCredentials} from "@/lib/ai/safeError";

type EditorState = {
    definition: ConnectorDefinition;
    existing?: ConnectorConfig;
};

type EditorSession = EditorState & {baseUrl: string; apiKey: string};
type EditorOperation = {session: EditorSession; kind: "probe" | "test" | "save" | "disconnect"};

export function ConnectorsPage() {
    const connectors = useLiveQuery(() => db.connectors.toArray(), []) ?? [];
    const byDefinition = useMemo(() => {
        const map = new Map<ConnectorDefinitionId, ConnectorConfig>();
        for (const connector of connectors) {
            map.set(connector.definitionId, connector);
        }
        return map;
    }, [connectors]);

    const [editor, setEditor] = useState<EditorState>();
    const [baseUrl, setBaseUrl] = useState("");
    const [apiKey, setApiKey] = useState("");
    const [probeModels, setProbeModels] = useState<string[]>([]);
    const [testing, setTesting] = useState(false);
    const [probing, setProbing] = useState(false);
    const [saving, setSaving] = useState(false);

    const mounted = useRef(true);
    const sessionRef = useRef<EditorSession | undefined>(undefined);
    const operationRef = useRef<EditorOperation | undefined>(undefined);
    const session = sessionRef.current;

    useEffect(() => {
        mounted.current = true;
        return () => {
            mounted.current = false;
            operationRef.current = undefined;
        };
    }, []);

    function writeLocked() {
        return operationRef.current?.kind === "save" || operationRef.current?.kind === "disconnect";
    }

    function currentOperation(operation: EditorOperation) {
        return mounted.current && sessionRef.current === operation.session && operationRef.current === operation;
    }

    function finishOperation(operation: EditorOperation) {
        if (!currentOperation(operation)) return;
        operationRef.current = undefined;
        setTesting(false);
        setProbing(false);
        setSaving(false);
    }

    function openEditor(definition: ConnectorDefinition, existing?: ConnectorConfig) {
        if (!mounted.current || writeLocked()) return;
        sessionRef.current = {definition, existing, baseUrl: existing?.baseUrl ?? definition.defaultBaseUrl, apiKey: ""};
        operationRef.current = undefined;
        setEditor({definition, existing});
        setBaseUrl(sessionRef.current.baseUrl);
        setApiKey("");
        setProbeModels([]);
        setTesting(false);
        setProbing(false);
        setSaving(false);
    }

    function closeEditor() {
        if (!mounted.current || sessionRef.current !== session || writeLocked()) return;
        sessionRef.current = undefined;
        operationRef.current = undefined;
        setEditor(undefined);
        setProbeModels([]);
        setTesting(false);
        setProbing(false);
        setSaving(false);
    }

    function changeCredential(field: "baseUrl" | "apiKey", value: string) {
        if (!mounted.current || !session || sessionRef.current !== session || writeLocked()) return;
        session[field] = value;
        // Transport has no AbortSignal: cancel publication and release only this
        // credential operation synchronously, before another callback can run.
        operationRef.current = undefined;
        setTesting(false);
        setProbing(false);
        setProbeModels([]);
        if (field === "baseUrl") setBaseUrl(value);
        else setApiKey(value);
    }

    function credentials() {
        return {
            definitionId: session!.definition.id,
            baseUrl: session!.baseUrl,
            apiKey: session!.apiKey.trim() || session!.existing?.apiKey || "",
        };
    }

    async function handleProbeModels() {
        if (!mounted.current || !session || sessionRef.current !== session || operationRef.current) return;
        const operation: EditorOperation = {session, kind: "probe"};
        const request = credentials();
        operationRef.current = operation;
        setProbing(true);
        try {
            const result = await listConnectorModels(request);
            if (!currentOperation(operation)) return;
            if (!result.ok) {
                toast.error(redactCredentials(result.message, request.apiKey).slice(0, 300));
                setProbeModels([]);
                return;
            }
            setProbeModels(result.models);
            toast.success(
                session.definition.id === "aihubmix"
                    ? `已获取 ${result.models.length} 个公开模型；API Key 请通过测试连接验证`
                    : result.models.length > 0
                        ? `探活成功，可见 ${result.models.length} 个模型`
                        : "探活成功，但接口未返回模型列表",
            );
        } catch (error) {
            if (currentOperation(operation)) toast.error(redactCredentials(error instanceof Error ? error.message : "拉取失败", request.apiKey).slice(0, 300));
        } finally {
            finishOperation(operation);
        }
    }

    async function handleTest() {
        if (!mounted.current || !session || sessionRef.current !== session || operationRef.current) return;
        const operation: EditorOperation = {session, kind: "test"};
        const request = credentials();
        operationRef.current = operation;
        setTesting(true);
        try {
            const result = await testConnectorConnection(request);
            if (!currentOperation(operation)) return;
            if (result.ok) {
                // Wait for the nested directory read before publishing success;
                // changing credentials retires both stages of this operation.
                if (result.via === "models") {
                    const listed = await listConnectorModels(request);
                    if (!currentOperation(operation)) return;
                    if (listed.ok) setProbeModels(listed.models);
                }
                const detail = result.via === "models" && result.modelCount != null
                    ? `（${result.modelCount} 个模型）` : "";
                toast.success(session.definition.id === "mimo" ? `模型目录读取成功${detail}；配音权限以实际生成为准` : result.via === "authenticated-read" ? "鉴权读取成功；具体模型权限以实际调用为准" : `连接成功${detail}`);
            } else {
                toast.error(redactCredentials(result.message, request.apiKey).slice(0, 300));
            }
        } catch (error) {
            if (currentOperation(operation)) toast.error(redactCredentials(error instanceof Error ? error.message : "测试失败", request.apiKey).slice(0, 300));
        } finally {
            finishOperation(operation);
        }
    }

    async function handleSave() {
        if (!mounted.current || !session || sessionRef.current !== session || operationRef.current) return;
        const operation: EditorOperation = {session, kind: "save"};
        const request = {...credentials(), protocol: session.definition.protocol, label: session.definition.title};
        operationRef.current = operation;
        setSaving(true);
        try {
            await upsertConnector(request);
            if (!currentOperation(operation)) return;
            operationRef.current = undefined;
            toast.success("已保存连接");
            closeEditor();
        } catch (error) {
            if (currentOperation(operation)) toast.error(redactCredentials(error instanceof Error ? error.message : "保存失败", request.apiKey).slice(0, 300));
        } finally {
            finishOperation(operation);
        }
    }

    async function handleDisconnect() {
        if (!mounted.current || !session?.existing || sessionRef.current !== session || operationRef.current) return;
        const operation: EditorOperation = {session, kind: "disconnect"};
        const request = credentials();
        const id = session.existing.id;
        operationRef.current = operation;
        setSaving(true);
        try {
            await deleteConnector(id);
            if (!currentOperation(operation)) return;
            operationRef.current = undefined;
            toast.success("已断开连接");
            closeEditor();
        } catch (error) {
            if (currentOperation(operation)) toast.error(redactCredentials(error instanceof Error ? error.message : "断开失败", request.apiKey).slice(0, 300));
        } finally {
            finishOperation(operation);
        }
    }

    return (
        <div className="px-4 py-6 md:px-10 md:py-8">
            <div className="max-w-3xl">
                <h1 className="font-display text-[28px] leading-none tracking-tight">连接</h1>
                <p className="text-muted-foreground mt-3 max-w-xl text-sm leading-6">
                    密钥仅保存在本机，配置一次后工作室与后续 Agent 共用。不会写入项目备份 ZIP。
                    具体聊天用哪个模型，在 Agent 对话里选择。
                </p>

                <div className="mt-8 flex flex-col gap-3">
                    {CONNECTOR_CATALOG.map((definition) => {
                        const existing = byDefinition.get(definition.id);
                        const connected = Boolean(existing);
                        return (
                            <Card
                                key={definition.id}
                                className={cn(
                                    "gap-4 py-5 shadow-none",
                                    connected ? "border-brand/35 bg-brand/[0.04]" : "bg-card/80",
                                )}
                            >
                                <CardHeader className="px-5">
                                    <div className="flex items-start gap-4">
                                        <div
                                            className="bg-muted text-foreground flex size-11 shrink-0 items-center justify-center rounded-2xl text-xs font-semibold tracking-wide"
                                            aria-hidden
                                        >
                                            {definition.mark}
                                        </div>
                                        <div className="min-w-0 flex-1">
                                            <CardTitle className="text-base">{definition.title}</CardTitle>
                                            <CardDescription className="mt-1.5 leading-5">
                                                {definition.blurb}
                                            </CardDescription>
                                        </div>
                                    </div>
                                    <CardAction>
                                        {connected ? (
                                            <Badge
                                                variant="outline"
                                                className="border-brand/40 bg-brand/10 text-brand gap-1"
                                            >
                                                <Check className="size-3" strokeWidth={2.5}/>
                                                已连接
                                            </Badge>
                                        ) : (
                                            <Badge variant="secondary">未连接</Badge>
                                        )}
                                    </CardAction>
                                </CardHeader>
                                <CardFooter className="justify-end gap-2 px-5">
                                    {connected ? (
                                        <Button
                                            variant="outline"
                                            size="sm"
                                            disabled={saving}
                                            onClick={() => openEditor(definition, existing)}
                                        >
                                            编辑
                                        </Button>
                                    ) : (
                                        <Button
                                            variant="brand"
                                            size="sm"
                                            disabled={saving}
                                            onClick={() => openEditor(definition)}
                                        >
                                            <Plug className="size-3.5"/>
                                            安装
                                        </Button>
                                    )}
                                </CardFooter>
                            </Card>
                        );
                    })}
                </div>
                <SearchConnection/>
            </div>

            <Dialog open={Boolean(editor)} onOpenChange={(open) => !open && closeEditor()}>
                <DialogContent
                    showCloseButton={!saving}
                    onEscapeKeyDown={(event) => {if (writeLocked()) event.preventDefault();}}
                    onPointerDownOutside={(event) => {if (writeLocked()) event.preventDefault();}}
                >
                    <DialogHeader>
                        <DialogTitle>{editor?.existing ? "编辑连接" : "安装连接"}</DialogTitle>
                        <DialogDescription>
                            {editor?.definition.id === "mimo"
                                ? "MiMo · 聊天和配音共用此连接。支持预置音色、音色设计与声音克隆；测试连接只读取模型目录，不发起生成。"
                                : editor?.definition.id === "aihubmix"
                                    ? "AIHubMix · 聊天、图像与视频共用此连接。模型目录公开可读；测试连接仅验证任务列表读取权限，不发起生成。"
                                    : editor?.definition.id === "apimart"
                                        ? "APIMart · 聊天、图像与视频共用此连接。测试连接仅查询模型，不发起生成。"
                                        : `${editor?.definition.title ?? ""} · OpenAI 兼容协议。此处只配置接入点；模型在聊天里选。`}
                        </DialogDescription>
                    </DialogHeader>
                    <div className="grid gap-4">
                        <Field label="Base URL">
                            <Input
                                value={baseUrl}
                                disabled={saving}
                                onChange={(event) => changeCredential("baseUrl", event.target.value)}
                                placeholder={editor?.definition.defaultBaseUrl}
                                autoComplete="off"
                            />
                        </Field>
                        <Field label="API Key">
                            <Input
                                type="password"
                                value={apiKey}
                                disabled={saving}
                                onChange={(event) => changeCredential("apiKey", event.target.value)}
                                placeholder={
                                    editor?.existing
                                        ? `已保存 ${maskApiKey(editor.existing.apiKey)}（留空则保持）`
                                        : "sk-…"
                                }
                                autoComplete="off"
                            />
                        </Field>
                        {probeModels.length > 0 ? (
                            <div className="bg-muted/40 rounded-lg border px-3 py-2">
                                <p className="text-muted-foreground text-xs">
                                    {editor?.definition.id === "aihubmix" ? "公开模型目录（前 12 个，不代表 Key 权限）" : "探活可见模型（前 12 个）"}
                                </p>
                                <p className="mt-1 text-xs leading-5 break-all">
                                    {probeModels.slice(0, 12).join(" · ")}
                                    {probeModels.length > 12 ? ` · …共 ${probeModels.length} 个` : ""}
                                </p>
                            </div>
                        ) : null}
                    </div>
                    <DialogFooter className="gap-2 sm:justify-between">
                        <div className="flex flex-wrap gap-2">
                            {editor?.existing ? (
                                <Button
                                    variant="ghost"
                                    className="text-destructive hover:text-destructive"
                                    disabled={testing || saving || probing}
                                    onClick={() => void handleDisconnect()}
                                >
                                    断开
                                </Button>
                            ) : null}
                        </div>
                        <div className="flex flex-wrap justify-end gap-2">
                            <Button
                                variant="outline"
                                disabled={testing || saving || probing}
                                onClick={() => void handleProbeModels()}
                            >
                                {probing ? "拉取中…" : editor?.definition.id === "aihubmix" ? "获取公开模型" : "拉取模型探活"}
                            </Button>
                            <Button
                                variant="outline"
                                disabled={testing || saving || probing}
                                onClick={() => void handleTest()}
                            >
                                {testing ? "测试中…" : "测试连接"}
                            </Button>
                            <Button
                                variant="brand"
                                disabled={testing || saving || probing}
                                onClick={() => void handleSave()}
                            >
                                {saving ? "保存中…" : "保存"}
                            </Button>
                        </div>
                    </DialogFooter>
                </DialogContent>
            </Dialog>
        </div>
    );
}
